'use strict';
const STORAGE='meta-bangla-course-v1',DAY=86400000,INTERVALS=[1,3,7,14,30];
const $=s=>document.querySelector(s),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),bn=n=>Number(n).toLocaleString('bn-BD');
const blank=()=>({version:1,school:'meta',read:{},notes:{},checks:{},quiz:{},seen:{},history:{},wrong:{},revision:{},portfolio:'',name:'',last:1});
const validId=id=>Number.isInteger(+id)&&+id>=1&&+id<=metaCourse.lessons.length;
const qFor=key=>{const [id,ix]=String(key).split(':');return validId(id)&&/^\d+$/.test(ix||'')?learningBank[id]?.[+ix]:null;};
function normalize(raw){
 if(!raw||raw.version!==1||raw.school!=='meta')throw Error('এটি Meta school-এর backup নয়।');
 const n=blank();for(const k of ['read','notes','checks','quiz','seen','history','wrong','revision'])if(raw[k]&&typeof raw[k]==='object'&&!Array.isArray(raw[k]))n[k]={...raw[k]};
 for(const [id,v] of Object.entries(n.read))if(!validId(id)||typeof v!=='boolean')delete n.read[id];
 for(const [id,v] of Object.entries(n.notes))if(!validId(id)||typeof v!=='string'||v.length>100000)delete n.notes[id];
 for(const [id,v] of Object.entries(n.checks))if(!validId(id)||!Array.isArray(v)||v.length!==3||!v.every(x=>typeof x==='boolean'))delete n.checks[id];
 for(const [id,v] of Object.entries(n.seen))if(!validId(id)||!Array.isArray(v))delete n.seen[id];else n.seen[id]=[...new Set(v.filter(k=>qFor(k)&&+k.split(':')[0]===+id))];
 for(const [id,s]of Object.entries(n.quiz)){if(!validId(id)||!s||!Array.isArray(s.ids)||s.ids.length!==6||new Set(s.ids).size!==6||!s.ids.every(k=>qFor(k)&&+k.split(':')[0]===+id)||!Array.isArray(s.answers)||s.answers.length>6||!s.answers.every(a=>Number.isInteger(a)&&a>=0&&a<3)||!Array.isArray(s.orders)||s.orders.length!==6||!s.orders.every(o=>Array.isArray(o)&&o.length===3&&new Set(o).size===3&&o.every(i=>[0,1,2].includes(i)))||!Number.isInteger(s.index)||s.index<0||s.index>6||s.answers.length<s.index||s.answers.length>s.index+1||!Number.isInteger(s.best)||s.best<0||s.best>6){delete n.quiz[id];}}
 for(const [key,h]of Object.entries(n.history))if(!qFor(key)||!h||!Number.isInteger(h.total)||h.total<1||!Number.isInteger(h.wrong)||h.wrong<0||h.wrong>h.total)delete n.history[key];
 for(const [key,w]of Object.entries(n.wrong))if(!qFor(key)||!w||!Number.isInteger(w.picked)||w.picked<0||w.picked>2)delete n.wrong[key];
 for(const [key,r]of Object.entries(n.revision))if(!qFor(key)||!r||!Number.isInteger(r.stage)||r.stage<0||r.stage>5||!Number.isFinite(r.due)||r.due<0)delete n.revision[key];
 for(const k of ['portfolio','name'])if(typeof raw[k]==='string')n[k]=raw[k].slice(0,k==='name'?80:100000);
 if(validId(raw.last))n.last=+raw.last;return n;
}
let state=blank(),storageOK=true,current=1,tab='read',revisionFeedback=null;
try{const raw=localStorage.getItem(STORAGE);if(raw)state=normalize(JSON.parse(raw));}catch{storageOK=false;}
function save(){try{localStorage.setItem(STORAGE,JSON.stringify(state));storageOK=true;return true;}catch{storageOK=false;toast('Save হয়নি—Resources থেকে backup নিন।');return false;}}
function toast(text){$('#toast').textContent=text;clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').textContent='',4000);}
function download(name,text,type='text/plain;charset=utf-8'){const url=URL.createObjectURL(new Blob([text],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function shuffle(list){const a=[...list];for(let i=a.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]];}return a;}
const mastered=id=>!!state.read[id]&&state.quiz[id]?.best===6;
const heading=(title,desc='')=>`<div class="eyebrow">META ADS পাঠশালা</div><h1>${esc(title)}</h1><p class="muted">${esc(desc)}</p>`;
const link=id=>`#m-lesson-${id}`;
function references(keys){return `<section class="card"><h3>Official reference</h3><ul>${keys.map(k=>`<li><a href="${esc(metaCourse.sources[k].url)}" target="_blank" rel="noopener noreferrer">${esc(metaCourse.sources[k].title)}</a>${metaCourse.sources[k].note?`<p class="small">${esc(metaCourse.sources[k].note)}</p>`:""}</li>`).join('')}</ul><p class="small">সূত্র: নতুন lesson ৯১–৯৬ review: ১১ অক্টোবর ২০২৬; আগের source review dates ঐতিহাসিক নথিতে আছে। UI/account options ভিন্ন হতে পারে; unavailable setting অনুমান করে ব্যবহার করবেন না।</p></section>`;}
function renderSidebar(){const count=metaCourse.lessons.filter(l=>mastered(l.id)).length;$('#sidebar').innerHTML=`<strong>${bn(count)}/${bn(metaCourse.lessons.length)} lesson mastered</strong><progress max="${metaCourse.lessons.length}" value="${count}"></progress><label class="field">Lesson খুঁজুন<input id="lesson-search" class="search" type="search" placeholder="Pixel, audience, Reels…"></label>${metaCourse.modules.map((m,i)=>`<details class="side-module" ${metaCourse.lessons[current-1]?.module===i?'open':''}><summary>${bn(i+1)} · ${esc(m.name)}</summary>${metaCourse.lessons.filter(l=>l.module===i).map(l=>`<a href="${link(l.id)}" data-search="${esc((l.title+' '+l.terms).toLowerCase())}" class="${location.hash===link(l.id)?'active':''}">${mastered(l.id)?'✓':bn(l.id)} · ${esc(l.title)}</a>`).join('')}</details>`).join('')}<p class="small">সব ${bn(metaCourse.modules.length)}টি module-এর ${bn(metaCourse.lessons.length)}টি lesson প্রস্তুত।</p>`;$('#lesson-search').oninput=e=>{const term=e.target.value.toLowerCase();document.querySelectorAll('.side-module').forEach(d=>{let hits=0;d.querySelectorAll('[data-search]').forEach(a=>{a.hidden=!a.dataset.search.includes(term);if(!a.hidden)hits++;});d.hidden=!hits;if(term)d.open=true;});};}
function route(){document.body.classList.remove('nav-open');$('#menu-toggle').setAttribute('aria-expanded','false');document.body.classList.remove('print-cheat');const hash=location.hash||'#home',m=hash.match(/^#m-lesson-(\d+)$/);document.title='Meta Ads পাঠশালা — বাংলায় শেখা ও অনুশীলন';if(m&&validId(m[1])){current=+m[1];state.last=current;save();tab='read';renderLesson();document.title=metaCourse.lessons[current-1].title+' — Meta Ads পাঠশালা';}else if(/^#m-cheat-\d+$/.test(hash)){renderCheat();}else{const routes={'#home':renderHome,'#syllabus':renderSyllabus,'#labs':renderLabs,'#sandbox':renderSandbox,'#revision':renderRevision,'#mistakes':renderMistakes,'#skills':renderSkills,'#cheats':renderCheat,'#m-cheat-1':renderCheat,'#portfolio':renderPortfolio,'#certificate':renderCertificate,'#glossary':renderGlossary,'#resources':renderResources,'#changelog':renderChangelog};if(routes[hash])routes[hash]();else $('#main').innerHTML=heading('এই পৃষ্ঠা পাওয়া যায়নি')+'<a class="button" href="#home">শেখার পথে ফিরুন</a>';}renderSidebar();document.querySelectorAll('#school-nav a').forEach(a=>a.classList.toggle('active',a.getAttribute('href')===hash));window.scrollTo({top:0});}
function renderHome(){const lessons=metaCourse.lessons,modules=metaCourse.modules,done=lessons.filter(l=>mastered(l.id)).length,resume=validId(state.last)?Number(state.last):1;$('#main').innerHTML=`<div class="meta-home"><div class="hero"><div><span class="eyebrow">EASY TEACHING · ZERO AD SPEND</span><h1>বুঝে শিখুন।<br>কাজ করে এগিয়ে যান।</h1><p>Meta Ads, Facebook ও Instagram campaign, Pixel ও CAPI—ভিত্তি থেকে বিস্তারিত setup ও advanced practice, সহজ বাংলায়। প্রতিটি lesson-এর পরে quiz, ভুলের ব্যাখ্যা এবং নিজের portfolio তৈরির কাজ।</p><div class="flex"><a class="button primary" href="#m-lesson-${resume}">${done||Object.keys(state.read).length?'যেখান থেকে থেমেছেন':'শেখা শুরু করুন'} ↗</a><a class="button primary" href="#skills">আমার Skill dashboard →</a><a class="button" href="#sandbox">Ads Manager demo →</a><a class="button" href="#labs">Practice lab →</a><a class="button text" href="#revision">Revision room →</a><a class="button text" href="#portfolio">Portfolio দেখুন →</a></div></div><div class="hero-art" aria-label="শেখার তিন ধাপ"><div class="path-node"><span class="path-icon">১</span><div><strong>ধারণা বুঝুন</strong><small>সহজ উদাহরণ · সঠিক Technical term</small></div></div><div class="path-node"><span class="path-icon">২</span><div><strong>নিজেকে যাচাই করুন</strong><small>Quiz · ব্যাখ্যা · আবার চেষ্টা</small></div></div><div class="path-node"><span class="path-icon">৩</span><div><strong>নিজের কাজ তৈরি করুন</strong><small>Practice · Portfolio · Evidence</small></div></div></div></div><div class="stats"><div class="stat"><strong>${bn(lessons.length)}</strong><span>Lesson · ${bn(modules.length)}টি module</span></div><div class="stat"><strong>${bn(Object.values(learningBank).reduce((sum,bank)=>sum+bank.length,0))}</strong><span>Question bank · round-এ ৬টি</span></div><div class="stat"><strong>${bn(done)} / ${bn(lessons.length)}</strong><span>আপনার mastered lessons</span></div></div><div class="two-col"><div class="card accent"><span class="eyebrow">আপনার learning routine</span><h2>প্রতিদিন একটি ছোট জয়</h2><p class="muted">১৫ মিনিট পড়ুন → ২৫ মিনিট practice → quiz দিন → ভুল বুঝে আবার চেষ্টা করুন। Foundation-এর পরে tracking, creative ও optimization-এর module অনুসরণ করুন। নিজের বোঝা ও practice অনুযায়ী সময় নিন।</p><a href="#m-lesson-${resume}" class="button">Lesson ${bn(resume)} খুলুন →</a></div><div class="card"><span class="eyebrow">Progress-এর নিয়ম</span><h3>পড়া + নতুন quiz-এ ৬/৬ = Mastered</h3><p class="small muted">সব lesson শুরু থেকেই খোলা। ভুল করলে শাস্তি নেই: ব্যাখ্যা পড়ুন, Hint ও feedback পড়ুন, তারপর unseen-first quiz retake দিন। Portfolio কাজ নিজে rubric দিয়ে review করবেন। Module certificate-এর জন্য practice note ও self-review-ও প্রয়োজন।</p><progress max="${lessons.length}" value="${done}" aria-label="Mastered lessons"></progress><p class="small">${bn(Math.round(done/lessons.length*100))}% learning progress</p></div></div><div class="section-title"><h2>আপনার বিস্তৃত learning path</h2><a class="small" href="#syllabus">সকল topic ও learning order →</a></div><div class="three-col">${modules.map((m,i)=>{const ls=lessons.slice(i*6,i*6+6),n=ls.filter(l=>mastered(l.id)).length;return `<section class="card module-card"><div class="card-head"><span class="module-num">MODULE ${String(i+1).padStart(2,'0')}</span><span class="pill gray">${bn(ls.length)}টি lesson</span></div><h3>${esc(m.name)}</h3><p class="muted">${esc(m.desc)}</p><progress value="${n}" max="${ls.length}" aria-label="${esc(m.name)} progress"></progress><div class="small muted">${bn(n)}/${bn(ls.length)} lesson mastered</div><a class="button" href="#m-lesson-${ls[0].id}">Module খুলুন →</a><a class="button text" href="#m-cheat-${i+1}">Cheat Sheet →</a></section>`;}).join('')}</div><div class="notice"><strong>বাস্তব প্রত্যাশা:</strong> এখানে কোনো campaign launch বা payment হয় না। Simulated practice দিয়ে ভিত্তি ও portfolio হবে; Expert judgement-এর জন্য পরে supervised live account experience প্রয়োজন। Meta interface ও policy বদলালে official resource যাচাই করুন।</div>${!storageOK?'<p class="bad">Progress save করা যাচ্ছে না। Resources থেকে backup নিন।</p>':''}</div>`;}
function renderSyllabus(){$('#main').innerHTML=heading('শেখার পূর্ণ পথ','সব ১৬টি module-এর ৯৬টি সম্পূর্ণ lesson এখন প্রকাশিত।')+metaCourse.roadmap.map((name,i)=>`<details class="card" ${i<metaCourse.modules.length?'open':''}><summary><strong>${bn(i+1)} · ${esc(name)}</strong> — ${i<metaCourse.modules.length?'প্রস্তুত':'পরবর্তী batch-এর পরিকল্পনা'}</summary>${i<metaCourse.modules.length?`<ol start="${i*6+1}">${metaCourse.lessons.filter(l=>l.module===i).map(l=>`<li><a href="${link(l.id)}">${esc(l.title)}</a></li>`).join('')}</ol><a href="#m-cheat-${i+1}">Module Cheat Sheet →</a>`:'<p>এই module-এর lesson এখনও এই release-এ যোগ করা হয়নি।</p>'}</details>`).join('');}
function renderLesson(){const l=metaCourse.lessons[current-1];$('#main').innerHTML=`<div class="crumb"><a href="/">হোম</a> / <a href="#home">Meta Ads</a> / Module ${bn(l.module+1)} / Lesson ${bn(current)}</div>${heading(l.title,l.goal)}<div class="flex"><button id="share">Lesson share</button><a class="button" href="#m-cheat-${l.module+1}">Cheat Sheet</a></div><div class="tabs" role="tablist" aria-label="Lesson অংশ">${[['read','পড়ুন'],['quiz','Quiz'],['practice','হাতে-কলমে']].map(([k,n])=>`<button role="tab" data-tab="${k}" aria-selected="${tab===k}" aria-controls="lesson-body">${n}</button>`).join('')}</div><section id="lesson-body" role="tabpanel"></section><nav class="flex no-print" aria-label="Lesson navigation">${current>1?`<a class="button" href="${link(current-1)}">← আগের lesson</a>`:''}${current<metaCourse.lessons.length?`<a class="button" href="${link(current+1)}">পরের lesson →</a>`:'<a class="button" href="#skills">আমার শেখার ফল →</a>'}</nav>`;document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{tab=b.dataset.tab;renderLesson();});$('#share').onclick=shareLesson;if(tab==='read')renderRead(l);else if(tab==='practice')renderPractice(l);else renderQuiz();}
async function shareLesson(){const url=location.href;try{if(navigator.share)await navigator.share({title:document.title,url});else if(navigator.clipboard){await navigator.clipboard.writeText(url);toast('Lesson link copy হয়েছে।');}else toast('Address bar থেকে এই lesson-এর link copy করুন।');}catch{toast('Share হয়নি—address bar থেকে link copy করতে পারেন।');}}
function renderRead(l){$('#lesson-body').innerHTML=[['সহজ অর্থ',l.plain],['পরিচিত উদাহরণ',l.analogy],['Technical bridge',l.terms]].map(([t,p])=>`<article class="card"><h2>${t}</h2><p>${esc(p)}</p></article>`).join('')+`<article class="card"><h2>ধাপে ধাপে করুন</h2><ol>${l.steps.map(s=>`<li>${esc(s)}</li>`).join('')}</ol></article><article class="card"><h2>একটি কাজের উদাহরণ</h2><p>${esc(l.example)}</p></article><div class="notice"><strong>যে ভুলটি এড়াবেন</strong><p>${esc(l.trap)}</p></div><details class="card"><summary>তিনটি self-check প্রশ্ন</summary>${l.qs.map(q=>`<details><summary>${esc(q.text)}</summary><p>${esc(q.options[q.answer])} — ${esc(q.why)}</p></details>`).join('')}</details><details class="card"><summary>আরেকবার যাচাই: ${esc(l.retry.text)}</summary><p>${esc(l.retry.options[l.retry.answer])} — ${esc(l.retry.why)}</p></details><label class="check"><input id="mark-read" type="checkbox" ${state.read[l.id]?'checked':''}> Lesson পড়েছি ও মূল ধারণা বুঝেছি</label>`+references(l.sources);$('#mark-read').onchange=e=>{state.read[l.id]=e.target.checked;save();renderSidebar();};}
function renderPractice(l){$('#lesson-body').innerHTML=`<article class="card"><h2>আপনার কাজ</h2><p>${esc(l.task)}</p><label class="field">আপনার practice note<textarea id="practice-note" rows="9">${esc(state.notes[l.id]||'')}</textarea></label><p id="save-status" role="status" class="small">লিখলেই এই browser-এ save হবে।</p><h3>নিজে মিলিয়ে দেখুন</h3>${l.rubric.map((r,i)=>`<label class="check"><input type="checkbox" data-check="${i}" ${state.checks[l.id]?.[i]?'checked':''}>${esc(r)}</label>`).join('')}<button id="note-export">এই কাজ .md export</button><p class="small">Self-review মানে স্বাধীনভাবে certified হওয়া নয়। Demo মানেই demo।</p></article>`;$('#practice-note').oninput=e=>{state.notes[l.id]=e.target.value;$('#save-status').textContent=save()?'Save হয়েছে ✓':'Save হয়নি—এখনই export করুন।';};document.querySelectorAll('[data-check]').forEach(el=>el.onchange=()=>{state.checks[l.id]??=[false,false,false];state.checks[l.id][+el.dataset.check]=el.checked;save();});$('#note-export').onclick=()=>download(`meta-lesson-${l.id}.md`,`# ${l.title}\n\nDemo / not run\n\n${state.notes[l.id]||''}\n\n## Self-review\n${l.rubric.map((r,i)=>`- [${state.checks[l.id]?.[i]?'x':' '}] ${r}`).join('\n')}`);}
function newAttempt(id){const all=learningBank[id].map((_,i)=>`${id}:${i}`),seen=state.seen[id]||[],fresh=shuffle(all.filter(k=>!seen.includes(k))),chosen=fresh.slice(0,6);if(chosen.length<6)chosen.push(...shuffle(all.filter(k=>!chosen.includes(k))).slice(0,6-chosen.length));state.quiz[id]={ids:shuffle(chosen),orders:Array.from({length:6},()=>shuffle([0,1,2])),answers:[],index:0,best:state.quiz[id]?.best||0};state.seen[id]=[...new Set([...seen,...chosen])];save();return state.quiz[id];}
function gradeQuiz(id,picked){const s=state.quiz[id];if(!s||s.index>=6||s.answers.length>s.index||![0,1,2].includes(picked))return;const key=s.ids[s.index],q=qFor(key),correct=picked===q.answer;s.answers.push(picked);const h=state.history[key]||{total:0,wrong:0};h.total++;if(!correct)h.wrong++;state.history[key]=h;if(correct)delete state.wrong[key];else state.wrong[key]={picked};state.revision[key]??={stage:0,due:Date.now()+(correct?DAY:0)};save();renderQuiz();}
function renderQuiz(){const s=state.quiz[current]||newAttempt(current);if(s.index===6){const score=s.answers.reduce((n,a,i)=>n+(a===qFor(s.ids[i]).answer),0);s.best=Math.max(s.best,score);save();renderSidebar();$('#lesson-body').innerHTML=`<section class="card"><h2>এই round: ${bn(score)}/৬</h2><p>Bank-এ ২০টি প্রশ্ন; এই round-এ ৬টি। নতুন round-এ আগে না-দেখা প্রশ্ন অগ্রাধিকার পাবে।</p><p>সেরা score: ${bn(s.best)}/৬ · দেখা হয়েছে ${bn(state.seen[current].length)}/২০</p><button id="retake" class="primary">নতুন round</button><a class="button" href="#mistakes">ভুলের ব্যাখ্যা</a></section>`;$('#retake').onclick=()=>{newAttempt(current);renderQuiz();};return;}const key=s.ids[s.index],q=qFor(key),answered=s.answers.length>s.index,picked=s.answers[s.index];$('#lesson-body').innerHTML=`<section class="card"><p class="eyebrow">প্রশ্ন ${bn(s.index+1)}/৬ · ২০ প্রশ্নের bank</p><h2>${esc(q.text)}</h2><div class="quiz-options">${s.orders[s.index].map(o=>`<button data-option="${o}" ${answered?'disabled':''}>${esc(q.options[o])}${answered&&picked===o?' ← আপনার উত্তর':''}</button>`).join('')}</div><button id="hint">Hint দেখুন</button><p id="hint-text" class="small"></p>${answered?`<div class="${picked===q.answer?'good':'bad'}"><strong>${picked===q.answer?'সঠিক হয়েছে':'আবার বুঝে নিই'}</strong><p>সঠিক উত্তর: ${esc(q.options[q.answer])}</p><p>${esc(q.why)}</p>${picked!==q.answer?`<p>${esc(metaCourse.lessons[current-1].plain)}</p>`:''}</div><button id="quiz-next" class="primary">${s.index===5?'ফল দেখুন':'পরের প্রশ্ন'}</button>`:''}</section>`;document.querySelectorAll('[data-option]').forEach(b=>b.onclick=()=>gradeQuiz(current,+b.dataset.option));$('#hint').onclick=()=>$('#hint-text').textContent=q.hints.join(' ');if(answered)$('#quiz-next').onclick=()=>{s.index++;save();renderQuiz();};}
function renderMistakes(){$('#main').innerHTML=heading('ভুলের খাতা','Main quiz-এ সঠিক উত্তর দিলে ওই প্রশ্ন এই তালিকা থেকে সরে যাবে।')+(Object.keys(state.wrong).length?Object.entries(state.wrong).map(([key,w])=>{const q=qFor(key),id=+key.split(':')[0];return `<article class="card"><h2>${esc(q.text)}</h2><p>আপনার উত্তর: ${esc(q.options[w.picked])}</p><p><strong>সঠিক:</strong> ${esc(q.options[q.answer])}</p><p>${esc(q.why)}</p><details><summary>ধারণাটি আবার পড়ুন</summary><p>${esc(metaCourse.lessons[id-1].plain)}</p></details><a href="${link(id)}">Lesson-এ ফিরে quiz দিন →</a></article>`;}).join(''):'<div class="card">এখন review বাকি নেই। Quiz-এ ভুল হলে এখানে explanation জমা হবে।</div>');}
function renderSkills(){let total=0,wrong=0;const rows=metaCourse.lessons.map(l=>{const hs=Object.entries(state.history).filter(([k])=>+k.split(':')[0]===l.id).map(([,v])=>v),n=hs.reduce((s,h)=>s+h.total,0),w=hs.reduce((s,h)=>s+h.wrong,0);total+=n;wrong+=w;return `<tr><td><a href="${link(l.id)}">${esc(l.title)}</a></td><td>${bn(n)}</td><td>${n?bn(Math.round(w/n*100))+'%':'এখনও data নেই'}</td><td>${mastered(l.id)?'Mastered':'চলছে'}</td></tr>`;}).join('');$('#main').innerHTML=heading('কোথায় আরও চর্চা করবেন','ভুলের হার = ভুল attempts ÷ মোট graded attempts × ১০০। এটি দক্ষতার স্বাধীন certification নয়।')+`<p>মোট graded attempts: ${bn(total)} · ভুল: ${bn(wrong)}</p><div class="table-wrap"><table><thead><tr><th>Topic</th><th>Attempts</th><th>ভুলের হার</th><th>অবস্থা</th></tr></thead><tbody>${rows}</tbody></table></div>`;}
function revisionGrade(key,correct,now=Date.now()){const r=state.revision[key]||{stage:0,due:now};if(correct){r.due=now+INTERVALS[Math.min(r.stage,4)]*DAY;r.stage=Math.min(5,r.stage+1);}else{r.stage=0;r.due=now+DAY;}state.revision[key]=r;save();}
function renderRevision(){const due=Object.keys(state.revision).filter(k=>state.revision[k].due<=Date.now()),key=due[0];$('#main').innerHTML=heading('Revision room','সঠিক হলে পরের review: ১ → ৩ → ৭ → ১৪ → ৩০ দিন। ভুল হলে পরের দিন। এগুলো local schedule, notification নয়।')+`<p>আজ due: ${bn(due.length)} · মোট scheduled: ${bn(Object.keys(state.revision).length)}</p>`;if(!key){$('#main').innerHTML+='<div class="card">এখন due প্রশ্ন নেই। Lesson quiz দিন, তারপর এখানে review ফিরবে।</div>';return;}const q=qFor(key);$('#main').innerHTML+=`<section class="card"><h2>${esc(q.text)}</h2><div class="quiz-options">${shuffle([0,1,2]).map(i=>`<button data-revision="${i}">${esc(q.options[i])}</button>`).join('')}</div><div id="revision-result"></div></section>`;document.querySelectorAll('[data-revision]').forEach(b=>b.onclick=()=>{const ok=+b.dataset.revision===q.answer;revisionGrade(key,ok);document.querySelectorAll('[data-revision]').forEach(x=>x.disabled=true);$('#revision-result').innerHTML=`<div class="${ok?'good':'bad'}">${ok?'সঠিক':'আবার পড়ুন'}: ${esc(q.options[q.answer])}<p>${esc(q.why)}</p></div><button id="revision-next">পরের review</button>`;$('#revision-next').onclick=renderRevision;});}
function renderPortfolio(){$('#main').innerHTML=heading('আপনার সৎ case study','Demo মানেই demo। Campaign না চালালে not run; expected result-কে actual বলবেন না।')+`<article class="card"><button id="template">খালি note-এ template বসান</button><label class="field">Case study<textarea id="portfolio" rows="16">${esc(state.portfolio)}</textarea></label><p id="portfolio-status" role="status" class="small"></p><button id="portfolio-export">Case study .md export</button></article>`;$('#portfolio').oninput=e=>{state.portfolio=e.target.value;$('#portfolio-status').textContent=save()?'Save হয়েছে ✓':'Save হয়নি';};$('#template').onclick=()=>{if(state.portfolio.trim()){toast('আগের লেখা রাখা হয়েছে।');return;}state.portfolio='# Demo case study — not run\n\nBusiness ও problem:\nGoal ও objective:\nAudience reasoning:\nStructure ও creative concept:\nMeasurement plan:\nDemo assumptions:\nকী কাজ করেছি:\nকী পরীক্ষা করেছি:\nActual result: campaign not run\nLimitations ও next step:\nOfficial sources:\n';save();renderPortfolio();};$('#portfolio-export').onclick=()=>download('meta-demo-case-study.md',state.portfolio);}
function renderFoundationCheat(){document.body.classList.add('print-cheat');$('#main').innerHTML=`<div class="no-print">${heading('Module ১ Cheat Sheet','এই release-এ প্রস্তুত module-এর এক পাতার summary।')}<button id="print-sheet" class="primary">Print / PDF</button><p class="small">A4 · Portrait · Scale 100% · Headers and footers বন্ধ রাখুন।</p></div><article class="card cheat"><span class="eyebrow">META ADS পাঠশালা · LESSON ১–৬</span><h2>ভিত্তি: সিদ্ধান্ত আগে, setup পরে</h2><h3>মূল কথা</h3><ol><li>Impression, click, enquiry ও paid order আলাদা outcome।</li><li>Business action → objective → conversion location → performance goal মিলান।</li><li>Auction-এ bid, estimated action rate ও ad quality গুরুত্বপূর্ণ; বেশি bid জয় নিশ্চিত করে না।</li><li>Campaign → Ad set → Ad; budget কোথায় আছে স্পষ্ট রাখুন।</li><li>Cold/warm/hot planning model; সবাই একই journey অনুসরণ করে না।</li><li>Asset ownership, প্রয়োজনমতো access ও 2FA review করুন। Password/OTP share নয়।</li></ol><h3>সূত্র ও সংজ্ঞা</h3><p>সরল CTR = Link clicks ÷ Impressions × ১০০। CPA = Cost ÷ নির্ধারিত outcome count।<br>Auction-এর ধারণাগত ব্যাখ্যা: Bid × Estimated action rate + Ad quality; এটি exact score calculator নয়।<br>Demo = শেখার জন্য বানানো data; actual client result নয়।</p><h3>তিনটি সাধারণ ভুল</h3><ul><li>Likes বা clicks-কে paid sale বলা।</li><li>Goal ঠিক না করে popular setting কপি করা।</li><li>কাজের প্রয়োজন ছাড়াই full control বা password দিয়ে দেওয়া।</li></ul><div class="remember"><strong>মনে রাখুন</strong><p>কোন business action চান, কীভাবে মাপবেন এবং user কী experience পাবেন—এই তিনটি প্রশ্ন দিয়ে শুরু করুন।</p></div><p class="small">পর্যালোচনা: ১১ অক্টোবর ২০২৬ · Official references প্রতিটি lesson-এ · স্বতন্ত্র শিক্ষাসহায়ক summary</p></article>`;$('#print-sheet').onclick=()=>window.print();}
function renderGlossary(){const rows=[['Scope','Agreed deliverables, boundaries ও dependencies',91],['Retainer','Agreed recurring service fee; ad spend আলাদা',91],['Least privilege','Task অনুযায়ী প্রয়োজনের minimum permissions',92],['Offboarding','Engagement শেষে access revoke ও handoff plan',92],['Audit backlog','Evidence-সহ prioritized findings/actions',93],['Data maturity','Outcome settle হওয়ার সময় ও reporting limitation',94],['Escalation','Unresolved issue appropriate owner/support-এ তোলা',95],['Certification','Official assessment credential; self-study record আলাদা',96],['Andromeda','Personalized ads retrieval engine; direct advertiser switch নয়',79],['GEM','Ads recommendation foundation model; image generator নয়',79],['Provenance','Asset creation history ও permissions',80],['Paid-use rights','Creator content paid advertising-এ ব্যবহারের অধিকার',81],['Opportunity score','Recommendations-এর সহায়ক view; profit certificate নয়',82],['Destination','Ad click/interaction-এর পরের journey; placement আলাদা',83],['Item ID','Stable catalog identifier; event mapping মিলতে হবে',85],['Product set','Catalog inventory-এর business-defined subset',86],['Contribution rate','Scoped before-ad contribution ÷ net realized revenue',88],['Source of truth','Authoritative business record',90],['Change log','পরিবর্তন, কারণ, owner ও rollback-এর নথি',67],['Creative fatigue','Message response কমার hypothesis; frequency একা প্রমাণ নয়',68],['Marginal cost','Extra spend ÷ extra outcomes; causal proof নয়',70],['Automated rule','Condition, action, scope ও evaluation window',71],['Personal Attributes','Viewer-এর sensitive অবস্থা assert/imply করা review করুন',74],['Authorization','Applicable product/geography-এর required permission',76],['Appeal','Official available decision-review path; reversal guarantee নয়',78],['Objective','Campaign-এর বড় উদ্দেশ্য',2],['Conversion location','Action যেখানে ঘটে',2],['Estimated action rate','কাঙ্ক্ষিত action-এর model probability',3],['Ad set','Delivery configuration-এর group',4],['Retargeting','আগের interaction-এর audience context',5],['2FA','Login-এ অতিরিক্ত verification',6],['Impression','Ad প্রদর্শনের count',1],['Pixel','Website browser signal-এর setup',7],['Event parameter','Action-এর supporting field',8],['CAPI','Server/integration event connection',9],['AEM','Privacy-aware measurement ধারণা',10],['Deduplication','Same action-এর redundant copy শনাক্ত',11],['Test Events','Debug receipt ও payload যাচাই',12],['CPQL','Cost ÷ Qualified leads',15],['Retention cohort','একই সময়ে আসা users-এর পরে ফিরে আসা',16],['Proxy metric','Final outcome-এর ভিন্ন indicator',18],["Broad audience", "অল্প অপ্রয়োজনীয় restriction-সহ audience approach", 19],["OR / AND", "যেকোনো শর্ত / একসঙ্গে শর্ত", 20],["Custom Audience", "আগের সম্পর্কের source-based group", 21],["Lookalike / Seed", "Source-এর মতো নতুন group / reference audience", 22],["Control / Suggestion", "সীমা / guidance", 23],["Confounder", "Test-এর ফল প্রভাবিত করা অন্য variable", 24],["Placement / Format", "কোথায় / কীভাবে বিজ্ঞাপন দেখাবে", 25],["Aspect ratio", "Width:height অনুপাত", 26],["Safe area", "UI overlay এড়িয়ে মূল content রাখার জায়গা", 27],["Carousel", "একাধিক card-এর presentation", 28],["Instant Experience", "In-app পূর্ণপর্দার অভিজ্ঞতা", 29],["QA matrix", "Asset ও placement অনুযায়ী পরীক্ষার evidence", 30],["Creative brief", "Goal থেকে production ও measurement plan", 31],["Benefit", "Feature-এর ব্যবহারিক উপকার", 32],["Hook", "প্রাসঙ্গিক opening attention cue", 33],["Testimonial", "বাস্তব experience-এর বক্তব্য", 34],["Concept / Execution", "মূল idea / উপস্থাপনা", 35],["Creative fatigue", "Repeated exposure-এ response কমার সম্ভাবনা", 36],["Pacing", "সময়ের মধ্যে spend বণ্টন", 37],["Budget allocation", "Ad sets-এর মধ্যে খরচ বণ্টন", 38],["Cost goal / Bid cap", "Average cost aim / auction bid limit", 39],["Contribution margin", "Contribution ÷ Revenue", 40],["Learning phase", "Delivery exploration-এর পর্যায়", 41],["Marginal cost", "অতিরিক্ত ফলের অতিরিক্ত cost diagnostic", 42],["Automation scope", "কোন কাজ system করছে", 43],["Readiness", "Signal, operations ও assets-এর প্রস্তুতি", 44],["Output QA", "শেষ creative-এর truth/readability review", 45],["Product media", "Product images/videos; আগের catalog ads terminology", 46],["Treatment", "Test-এ বদলানো setup", 47],["Business reconciliation", "Platform ফল actual records-এর সঙ্গে মিলানো", 48],["Funnel / Cohort", "Journey stages / defined group", 49],["Recency segment", "Action ও সময়সীমাভিত্তিক group", 50],["Suppression", "অপ্রাসঙ্গিক message বন্ধের rule", 51],["Cross-sell / Upsell", "Complementary item / higher-value option", 52],["Win-back", "Lapsed customer ফিরিয়ে আনার চেষ্টা", 53],["Holdout / Lift", "Treatment ছাড়া comparison / incremental outcome estimate", 54]];$('#main').innerHTML=heading('Technical শব্দ, সহজ অর্থ')+rows.map(([t,d,id])=>`<article class="card"><h2>${t}</h2><p>${d}</p><a href="${link(id)}">সম্পর্কিত lesson →</a></article>`).join('');}
function certificateEligible(moduleIndex=0){return metaCourse.lessons.filter(l=>l.module===moduleIndex).every(l=>mastered(l.id)&&state.notes[l.id]?.trim()&&state.checks[l.id]?.every(Boolean));}
function renderCertificate(moduleIndex=0){const title=metaCourse.modules[moduleIndex].name;$('#main').innerHTML=heading('Module completion record','এটি নির্বাচিত module-এর self-study record; official Meta certification বা পুরো course-এর completion certificate নয়।')+`<label class="field">Module<select id="certificate-module">${metaCourse.modules.map((m,i)=>`<option value="${i}" ${i===moduleIndex?'selected':''}>${bn(i+1)} · ${esc(m.name)}</option>`).join('')}</select></label><p>এই module-এর ৬টি lesson পড়া, প্রতিটিতে quiz ৬/৬, practice note ও তিনটি self-review check প্রয়োজন।</p><label class="field">আপনার নাম<input id="learner-name" maxlength="80" value="${esc(state.name)}"></label><button id="certificate" ${certificateEligible(moduleIndex)?'':'disabled'}>Certificate তৈরি করুন</button><p id="certificate-status" role="status">${certificateEligible(moduleIndex)?'শর্ত পূরণ হয়েছে।':'এই module-এর কিছু lesson বা practice বাকি।'}</p><div id="certificate-output"></div>`;$('#certificate-module').onchange=e=>renderCertificate(+e.target.value);$('#learner-name').oninput=e=>{state.name=e.target.value;save();};$('#certificate').onclick=async()=>{if(!certificateEligible(moduleIndex)||!state.name.trim()){toast('নাম লিখুন ও শর্ত পূরণ করুন।');return;}if(document.fonts)await document.fonts.ready;const c=document.createElement('canvas');c.width=1600;c.height=1000;const x=c.getContext('2d');x.fillStyle='#fffef8';x.fillRect(0,0,1600,1000);x.strokeStyle='#176b53';x.lineWidth=12;x.strokeRect(40,40,1520,920);x.fillStyle='#176b53';x.textAlign='center';x.font='bold 52px Bangla';x.fillText('Meta Ads পাঠশালা',800,170);x.font='38px Bangla';x.fillText('Module '+bn(moduleIndex+1)+' — শেখা সম্পন্নের record',800,265);x.font='28px Bangla';x.fillText(title,800,330);let size=64;do{x.font=`bold ${size--}px Bangla`;}while(x.measureText(state.name).width>1400&&size>22);x.fillText(state.name,800,470);x.font='30px Bangla';x.fillText('৬টি lesson · Quiz mastery · Self-reviewed practice',800,585);x.fillText('স্বতন্ত্র শিক্ষামূলক record — Meta certification নয়',800,675);x.font='25px Bangla';x.fillText(new Date().toLocaleDateString('bn-BD'),800,790);$('#certificate-output').replaceChildren(c);const a=document.createElement('a');a.className='button';a.textContent='PNG download';a.href=c.toDataURL('image/png');a.download=`meta-module-${moduleIndex+1}-completion.png`;$('#certificate-output').appendChild(a);};}
function renderResources(){$('#main').innerHTML=heading('Resources ও progress backup','Meta ও Google school-এর progress আলাদা। একই domain-এর path বদলালে browser storage key ঠিক থাকলে progress থাকে।')+`<div class="card"><button id="backup-export">Meta backup export</button><button id="backup-import">Meta backup import</button><p class="small">Import বর্তমান Meta progress replace করবে। আগে export করে রাখুন। Google backup এখানে import হবে না।</p></div>`+references(Object.keys(metaCourse.sources));$('#backup-export').onclick=()=>download('meta-progress-backup.json',JSON.stringify(state,null,2),'application/json');$('#backup-import').onclick=()=>$('#import-file').click();}
$('#import-file').onchange=async e=>{const file=e.target.files?.[0];if(!file)return;try{if(file.size>3000000)throw Error('Backup file খুব বড়।');const parsed=normalize(JSON.parse(await file.text()));if(!window.confirm('বর্তমান Meta progress replace করবেন? আগে backup export করে রাখুন।'))return;state=parsed;save();route();toast('Meta backup import হয়েছে।');}catch(err){toast(err.message||'Backup পড়া যায়নি।');}finally{e.target.value='';}};
function renderChangelog(){$('#main').innerHTML=heading('নতুন কী','v1.8.1 · Browser QA update')+'<article class="card"><h2>Module ১৬: Professional practice</h2><ul><li>Lesson ৯১–৯৬: ছয়টি পূর্ণ lesson, ১২০টি নতুন প্রশ্ন ও Module ১৬ cheat sheet।</li><li>সব ১৬টি module / ৯৬টি lesson / ১,৯২০টি প্রশ্ন / ১৬টি sheet প্রকাশিত।</li><li>Services/pricing, onboarding/access, audit, reporting, troubleshooting এবং official learning roadmap।</li><li>আগের ৯০টি Meta lesson/প্রশ্ন ও Google school content অক্ষত।</li></ul><p>Curriculum batches সম্পন্ন। Lessons-এর practice দিয়ে honest demo portfolio বানান; official Meta certification আলাদা।</p><h3>Verification সীমা</h3><p>Code ও DOM-double logic checks হয়েছে। Hosted v1.8-এ তিন sample lesson-এর real reload/read/note/quiz এবং Google read/note/legacy redirect tested; captured logs-এ site-origin errors পাওয়া যায়নি। Mobile viewport ও one-page print preview এখনও অসম্পূর্ণ। Full gated training/account UI/region eligibility যাচাই হয়নি। START-HERE-BN.txt ও FINAL-VERIFICATION-BN.txt পড়ুন।</p></article>';}
