function ratio(n,d,scale=1){return d>0?n/d*scale:null;}
function metricValues(d){return {CPM:ratio(d.cost,d.impressions,1000),CTR:ratio(d.clicks,d.impressions,100),CPC:ratio(d.cost,d.clicks),CVR:ratio(d.conversions,d.clicks,100),CPA:ratio(d.cost,d.conversions),ROAS:ratio(d.value,d.cost)};}
function fmt(n,suffix=''){return n===null?'—':n.toLocaleString('bn-BD',{maximumFractionDigits:2})+suffix;}
function numField(id,title,value){return `<label class="field">${title}<input id="${id}" type="number" min="0" step="any" value="${value}"></label>`;}
function renderLabs(){$('#main').innerHTML=heading('Practice labs','সব output শিক্ষামূলক simulation। কোনো real ad account-এ setting পাঠানো হয় না।')+`<nav class="flex no-print"><a class="button" href="#labs" data-lab="metrics">Metrics</a><button data-lab="audience">Audience builder</button><button data-lab="creative">Creative check</button><button data-lab="policy">Copy risk check</button><button data-lab="attribution">Attribution</button></nav><div id="lab-body"></div>`;document.querySelectorAll('[data-lab]').forEach(b=>b.onclick=e=>{e.preventDefault();showLab(b.dataset.lab);});showLab('metrics');}
function showLab(kind){const el=$('#lab-body');if(kind==='metrics'){el.innerHTML=`<section class="card"><h2>Metric calculator · demo</h2><div class="grid">${[['cost','খরচ (৳)',1200],['impressions','Impressions',10000],['clicks','Link clicks',200],['conversions','নির্ধারিত conversions',10],['value','Conversion value (৳)',5000]].map(([id,t,v])=>numField('metric-'+id,t,v)).join('')}</div><div id="metric-output" role="status"></div><p class="small">CTR এখানে link CTR, CVR click-based। Revenue ROAS net profit নয়। Zero denominator-এ “—”।</p></section>`;const update=()=>{const d={};let ok=true;for(const k of ['cost','impressions','clicks','conversions','value']){const field=$('#metric-'+k);d[k]=Number(field.value);if(!field.value.trim()||!Number.isFinite(d[k])||d[k]<0)ok=false;}$('#metric-output').innerHTML=ok?`<div class="table-wrap"><table><tr>${Object.keys(metricValues(d)).map(k=>`<th>${k}</th>`).join('')}</tr><tr>${Object.entries(metricValues(d)).map(([k,v])=>`<td>${fmt(v,['CTR','CVR'].includes(k)?'%':k==='ROAS'?'×':'')}</td>`).join('')}</tr></table></div>`:'<p class="bad">সব ঘরে শূন্য বা positive সংখ্যা দিন।</p>';};document.querySelectorAll('#lab-body input').forEach(i=>i.oninput=update);update();}
else if(kind==='audience'){el.innerHTML=`<section class="card"><h2>Audience reasoning builder · demo</h2><label class="field">Business offer<input id="aud-offer" value="ঢাকায় cotton shirt delivery"></label><label class="field">Service area<input id="aud-area" value="ঢাকা"></label><label class="field">Relationship<select id="aud-stage"><option>নতুন পরিচয়</option><option>আগে engagement করেছে</option><option>আগের customer</option></select></label><label class="field">Category<select id="aud-category"><option value="general">সাধারণ demo retail</option><option value="special">Housing / employment / financial category</option></select></label><label class="field">Permission ও exclusion reasoning<textarea id="aud-reason" rows="3">শুধু অনুমোদিত data; prior buyers-এর প্রয়োজন আলাদা করে review করব।</textarea></label><button id="aud-build">Plan তৈরি করুন</button><div id="aud-output"></div></section>`;$('#aud-build').onclick=()=>{$('#aud-output').innerHTML=`<div class="notice"><strong>Planning brief — targeting prediction নয়</strong><p>Offer: ${esc($('#aud-offer').value)}<br>Service area: ${esc($('#aud-area').value)}<br>Relationship: ${esc($('#aud-stage').value)}</p><p>${esc($('#aud-reason').value)}</p><p>${$('#aud-category').value==='special'?'বিশেষ category-এর applicable rules আগে যাচাই করুন; এই tool দিয়ে eligibility বা targeting অনুমোদন হয় না।':'Reach estimate নয়। Available audience controls, consent ও offer fit আলাদা যাচাই করুন।'}</p></div>`;};}
else if(kind==='creative'){el.innerHTML=`<section class="card"><h2>Creative geometry checker</h2><p>এটি common aspect-ratio practice; Meta approval, file-size বা duration validator নয়। Placement-এর current spec official page-এ যাচাই করুন।</p><div class="grid">${numField('creative-width','Width (px)',1080)}${numField('creative-height','Height (px)',1920)}</div><label class="field">Practice ratio<select id="creative-ratio"><option value="0.5625">9:16 vertical</option><option value="0.8">4:5 portrait</option><option value="1">1:1 square</option></select></label><label class="check"><input id="creative-safe" type="checkbox">Preview-তে text/logo UI overlay-এর আড়ালে নেই যাচাই করেছি</label><div id="creative-output" role="status"></div><a href="${metaCourse.sources.placements.url}" target="_blank" rel="noopener noreferrer">Official placement guidance →</a></section>`;const update=()=>{const w=+$('#creative-width').value,h=+$('#creative-height').value,t=+$('#creative-ratio').value;$('#creative-output').innerHTML=w>0&&h>0?`<div class="notice">Ratio ${Math.abs(w/h-t)<0.005?'মিলেছে':'মেলেনি'}। Safe-zone review: ${$('#creative-safe').checked?'নিজে যাচাই করেছেন':'এখনও বাকি'}।<p>ছোট text, captions, crop ও actual placement preview আলাদা দেখুন। কোনো এক universal safe-zone pixel rule এখানে দাবি করা হচ্ছে না।</p></div>`:'<p class="bad">Width ও height শূন্যের বেশি দিন।</p>';};document.querySelectorAll('#lab-body input,#lab-body select').forEach(i=>i.oninput=update);update();}
else if(kind==='policy'){el.innerHTML=`<section class="card"><h2>Ad-copy risk checker</h2><p>এই local pattern checker কিছু personal-attribute ও misleading-claim ঝুঁকি চিহ্নিত করে। Context, image বা সব ভাষা বোঝে না; flag না পাওয়া মানে approval নয়।</p><label class="field">আপনার demo copy<textarea id="policy-copy" placeholder="এখানে demo ad copy লিখুন…"></textarea></label><button id="policy-check">ঝুঁকি দেখুন</button><div id="policy-output" role="status"></div><a href="${metaCourse.sources.policy.url}" target="_blank" rel="noopener noreferrer">Meta Advertising Standards →</a></section>`;$('#policy-check').onclick=()=>{const value=$('#policy-copy').value.trim();const flags=policyFlags(value);$('#policy-output').innerHTML=!value?'<p>আগে copy লিখুন।</p>':`<div class="notice">${flags.length?'<ul>'+flags.map(f=>`<li>${esc(f)}</li>`).join('')+'</ul>':'এই সীমিত pattern set-এ flag নেই। এটি approval বা compliance guarantee নয়।'}<p>ব্যক্তির পরিচয়/স্বাস্থ্য/আর্থিক অবস্থা ধরে কথা না বলে service ও যাচাইযোগ্য offer স্পষ্ট করুন। দাবি সমর্থনের evidence এবং destination-ও review করুন।</p></div>`;};}
else{el.innerHTML=`<section class="card"><h2>Attribution simulator · demo</h2><p>একটি কাল্পনিক journey-তে তিন touchpoint-এর মধ্যে ৳৩,০০০ sale credit কীভাবে বদলায় দেখুন। এটি Meta-এর actual attribution model নয়।</p><ol><li>প্রথম ad touch</li><li>দ্বিতীয় ad touch</li><li>Direct visit ও purchase</li></ol><label class="field">শেখার model<select id="attr-model"><option value="first">First touch</option><option value="last">Last touch</option><option value="linear">Linear</option></select></label>${numField('attr-value','Demo sale value (৳)',3000)}<div id="attr-output" role="status"></div><p class="notice">Credit ভাগ বদলালেও মোট sale একই। Ad না থাকলে sale হতো কি না জানতে আলাদা causal test দরকার।</p></section>`;const update=()=>{const v=+$('#attr-value').value;if(!Number.isFinite(v)||v<0){$('#attr-output').textContent='শূন্য বা positive value দিন।';return;}const m=$('#attr-model').value,values=m==='first'?[v,0,0]:m==='last'?[0,0,v]:[v/3,v/3,v/3];$('#attr-output').innerHTML=`<ul>${values.map((n,i)=>`<li>Touch ${bn(i+1)}: ৳${fmt(n)}</li>`).join('')}</ul>`;};$('#attr-model').onchange=update;$('#attr-value').oninput=update;update();}}
function policyFlags(text){const flags=[];if(/(আপনি|আপনার|তুমি|তোমার|you|your).{0,45}(ডায়াবেট|ডায়াবেট|ঋণ|বেকার|অসুস্থ|মোটা|debt|diabet|unemploy|overweight)/i.test(text))flags.push('ব্যক্তির health/financial/personal অবস্থা ধরে নেওয়ার সম্ভাব্য ঝুঁকি।');if(/(১০০%|100%|নিশ্চিত|guarantee|guaranteed).{0,30}(লাভ|আয়|আয়|সুস্থ|income|profit|cure)/i.test(text)||/(রাতারাতি ধনী|instant cure|risk.free profit)/i.test(text))flags.push('নিশ্চিত বা অবাস্তব outcome-এর সম্ভাব্য দাবি; evidence ও policy review দরকার।');if(/(আগে.{0,15}পরে|before.{0,15}after)/i.test(text))flags.push('Before/after wording: product category, image ও applicable policy context review করুন। এটি সব category-তে এক blanket verdict নয়।');return flags;}
